<?php require_once 'includes/db.php';if(session_status()!==PHP_SESSION_ACTIVE)session_start();$_SESSION['cart']??=[];$a=$_POST['action']??'';if($a==='add'){$id=(int)$_POST['product_id'];$q=max(1,(int)$_POST['quantity']);$s=db()->prepare('SELECT stock FROM products WHERE id=? AND active=1');$s->execute([$id]);if($p=$s->fetch())$_SESSION['cart'][$id]=min($p['stock'],($_SESSION['cart'][$id]??0)+$q);header('Location: cart.php');exit;}if($a==='update'){foreach($_POST['qty']??[] as $id=>$q){$id=(int)$id;$q=(int)$q;if($q<=0)unset($_SESSION['cart'][$id]);else$_SESSION['cart'][$id]=$q;}header('Location: cart.php');exit;}if(isset($_GET['remove'])){unset($_SESSION['cart'][(int)$_GET['remove']]);header('Location: cart.php');exit;}$items=[];$total=0;if($_SESSION['cart']){$ids=array_keys($_SESSION['cart']);$in=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT * FROM products WHERE id IN($in) AND active=1");$s->execute($ids);foreach($s as $p){$p['quantity']=$_SESSION['cart'][$p['id']];$p['subtotal']=$p['quantity']*$p['price'];$total+=$p['subtotal'];$items[]=$p;}}$title='Cart - '.APP_NAME;include 'includes/header.php';?><h1>Your Cart</h1><?php if(!$items):?><div class="notice">Your cart is empty.</div><?php else:?><form method="post"><input type="hidden" name="action" value="update"><table class="table"><tr><th>Product</th><th>Price</th><th>Qty</th><th>Subtotal</th><th></th></tr><?php foreach($items as $p):?><tr><td><?=htmlspecialchars($p['name'])?></td><td>KES <?=number_format($p['price'],2)?></td><td><input type="number" name="qty[<?=$p['id']?>]" value="<?=$p['quantity']?>" min="0" max="<?=$p['stock']?>"></td><td>KES <?=number_format($p['subtotal'],2)?></td><td><a href="cart.php?remove=<?=$p['id']?>">Remove</a></td></tr><?php endforeach;?></table><br><button class="btn">Update Cart</button> <a class="btn" href="checkout.php">Checkout</a></form><?php endif;?><?php include 'includes/footer.php';?>